      opacity: 1;
    }

    .section {
      background: rgba(18, 32, 60, 0.8);
      border-radius: 8px;
      padding: 10px 12px;
      border-left: 3px solid #6fffbe33;
      width: calc(50% - 5px);
      box-sizing: border-box;
      box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
      transition: transform 0.2s ease;
    }

    .section.purple {
      border-left: 3px solid rgba(187, 134, 252, 0.4);
      background: rgba(24, 18, 60, 0.8);
    }

    .section:hover {
      transform: translateY(-2px);
    }

    .section-label {
      font-weight: bold;
      font-size: 1rem;
      color: #7fffd4;
      margin-bottom: 8px;
      position: relative;
    }

    .section-label:after {
      content: '';
      position: absolute;
      bottom: -3px;
      left: 0;
      width: 100%;
      height: 1px;
      background: linear-gradient(90deg, #7fffd4, transparent);
    }

    .section.purple .section-label {
      color: #bb86fc;
    }

    .section.purple .section-label:after {
      background: linear-gradient(90deg, #bb86fc, transparent);
    }

    .sub-label {
      font-size: 0.9rem;
      color: #7fffd4;
      margin: 8px 0 4px 4px;
      font-weight: bold;
      text-shadow: 0 0 3px rgba(111, 255, 190, 0.3);
    }

