      flex-wrap: wrap;
      gap: 6px;
    }

    .option-label {
      display: flex;
      align-items: center;
      background: rgba(40, 80, 160, 0.3);
      border-radius: 5px;
      padding: 4px 8px;
      cursor: pointer;
      transition: background 0.2s, box-shadow 0.2s;
      font-size: 0.9rem;
