      background: rgba(120, 40, 160, 0.35);
      box-shadow: 0 0 8px rgba(187, 134, 252, 0.3);
    }

    .option-label input {
      display: none;
    }

    .option-label span {
      position: relative;
      padding-left: 20px;
    }

    .option-label span:before {
      content: '';
      position: absolute;
      left: 0;
      top: 50%;
      transform: translateY(-50%);
      width: 14px;
      height: 14px;
      border: 1px solid #6fffbe;
      background: rgba(20, 40, 80, 0.5);
      border-radius: 3px;
      transition: background-color 0.2s;
