      // 第五页
      {
        name: 'morality',
        label: '关键角色道德倾向',
        type: 'radio',
        options: ['绝对正义', '中立善良', '冷酷无情', '自私自利', '混乱邪恶', '忠诚守信', '随心所欲', '自定义']
      },
      {
        name: 'ability',
        label: '关键角色特殊能力',
        type: 'radio',
        options: [
          '魔法掌控', '超凡力量', '隐形潜行', '治愈术', '元素支配', '无特殊能力',
          '黑客技术', '心理洞察', '谈判专家',
          '书法大师', '剑术宗师', '机关术',
          '龙语魔法', '星辰预言', '灵魂契约', '自定义'
        ],
        groups: [
          { label: '现代都市', options: ['黑客技术', '心理洞察', '谈判专家'] },
          { label: '古代', options: ['书法大师', '剑术宗师', '机关术'] },
          { label: '奇幻', options: ['魔法掌控', '超凡力量', '隐形潜行', '治愈术', '元素支配', '龙语魔法', '星辰预言', '灵魂契约'] },
          { label: '其他', options: ['无特殊能力', '自定义'] }
        ]
      }
    ];

    // 动态生成 HTML
    function renderPages() {
      const pagesDiv = document.getElementById('pages');
      const itemsPerPage = 4;
      const totalPages = Math.ceil(categories.length / itemsPerPage);
      console.log(`Total categories: ${categories.length}, Total pages: ${totalPages}`); // 调试日志

      for (let page = 1; page <= totalPages; page++) {
        const pageDiv = document.createElement('div');
        pageDiv.className = `page ${page === 1 ? 'active' : ''}`;
        pageDiv.dataset.page = page;

        const start = (page - 1) * itemsPerPage;
        const end = Math.min(start + itemsPerPage, categories.length);
        console.log(`Rendering page ${page}: categories ${start} to ${end}`); // 调试日志

        categories.slice(start, end).forEach(category => {
          const section = document.createElement('div');
          section.className = `section ${category.purple ? 'purple' : ''}`;
          let optionsHTML = '';

          if (category.groups) {
            category.groups.forEach(group => {
              optionsHTML += `<div class="sub-label">${group.label}</div>`;
              optionsHTML += `<div class="option-group">`;
              group.options.forEach(option => {
                optionsHTML += `
                  <label class="option-label">
                    <input type="${category.type}" name="${category.name}${category.multi && option === '自定义' ? '-custom-toggle' : ''}" value="${option}">
                    <span>${option}</span>
                  </label>
                `;
              });
              optionsHTML += `</div>`;
            });
          } else {
            optionsHTML = `
              <div class="option-group">
                ${category.options.map(option => `
                  <label class="option-label">
                    <input type="${category.type}" name="${category.name}${category.multi && option === '自定义' ? '-custom-toggle' : ''}" value="${option}">
                    <span>${option}</span>
                  </label>
                `).join('')}
              </div>
            `;
          }

          section.innerHTML = `
            <div class="section-label">${category.label}${category.multi ? '<span class="multi-select-badge">可多选</span>' : ''}</div>
            ${optionsHTML}
            <div class="custom-input" id="${category.name}-custom" style="display:none;">
              <input type="text" id="${category.name}-custom-input" placeholder="请输入自定义${category.label}...">
            </div>
          `;
          pageDiv.appendChild(section);
        });

        pagesDiv.appendChild(pageDiv);
      }

      document.getElementById('page-indicator').textContent = `第 1/${totalPages} 页`;
    }

    // 分页逻辑
    let currentPage = 1;
    const prevBtn = document.getElementById('prev-btn');
    const nextBtn = document.getElementById('next-btn');
    const pageIndicator = document.getElementById('page-indicator');

    function updatePagination() {
      const totalPages = document.querySelectorAll('.page').length;
      console.log(`Updating pagination: currentPage=${currentPage}, totalPages=${totalPages}`); // 调试日志
      document.querySelectorAll('.page').forEach(page => {
        page.classList.toggle('active', parseInt(page.dataset.page) === currentPage);
      });
      prevBtn.disabled = currentPage === 1;
      nextBtn.disabled = currentPage === totalPages;
      pageIndicator.textContent = `第 ${currentPage}/${totalPages} 页`;
    }

    prevBtn.addEventListener('click', () => {
      if (currentPage > 1) {
        currentPage--;
        updatePagination();
      }
    });

    nextBtn.addEventListener('click', () => {
      const totalPages = document.querySelectorAll('.page').length;
      if (currentPage < totalPages) {
        currentPage++;
        updatePagination();
      }
    });

    // 动态绑定事件
    function bindEvents() {
      categories.forEach(category => {
        const inputs = document.querySelectorAll(`input[name="${category.name}"], input[name="${category.name}-custom-toggle"]`);
        const customDiv = document.getElementById(`${category.name}-custom`);
        if (customDiv) {
          inputs.forEach(input => {
            input.addEventListener('click', (e) => {
              const isChecked = input.checked;
              const isCustomToggle = input.name.includes('custom-toggle');

              if (category.type === 'radio' && isChecked && input.dataset.wasChecked === 'true') {
                // 取消单选框选择
                input.checked = false;
                input.dataset.wasChecked = 'false';
                if (input.value === '自定义' || isCustomToggle) {
                  customDiv.style.display = 'none';
                }
              } else if (category.type === 'radio') {
                // 单选框选中
                inputs.forEach(i => {
                  i.dataset.wasChecked = i === input ? 'true' : 'false';
                });
                customDiv.style.display = (input.value === '自定义' || (isCustomToggle && input.checked)) ? 'block' : 'none';
              } else if (category.type === 'checkbox') {
                // 复选框逻辑
                input.dataset.wasChecked = isChecked ? 'true' : 'false';
                if (isCustomToggle) {
                  customDiv.style.display = input.checked ? 'block' : 'none';
                }
              }
            });

            // 记录初始状态
            input.dataset.wasChecked = input.checked ? 'true' : 'false';
          });
        }
      });
    }

    // 随机选择函数
    function randomSelect() {
      categories.forEach(category => {
        const inputs = document.querySelectorAll(`input[name="${category.name}"]`);
        const customToggle = document.querySelector(`input[name="${category.name}-custom-toggle"]`);
        const customInput = document.getElementById(`${category.name}-custom-input`);
        const customDiv = document.getElementById(`${category.name}-custom`);

        if (category.type === 'radio') {
          const options = Array.from(inputs).filter(input => input.value !== '自定义');
          inputs.forEach(input => {
            input.checked = false;
            input.dataset.wasChecked = 'false';
          });
          const randomOption = options[Math.floor(Math.random() * options.length)];
          randomOption.checked = true;
          randomOption.dataset.wasChecked = 'true';

          customDiv.style.display = 'none';
          if (customInput) customInput.value = '';
        } else if (category.type === 'checkbox') {
          const options = Array.from(inputs).filter(input => input.value !== '自定义');
          const selectCount = Math.floor(Math.random() * 3) + 1;
          options.forEach(opt => {
            opt.checked = false;
            opt.dataset.wasChecked = 'false';
          });
          for (let i = 0; i < selectCount && i < options.length; i++) {
            const randomOption = options.splice(Math.floor(Math.random() * options.length), 1)[0];
            randomOption.checked = true;
            randomOption.dataset.wasChecked = 'true';
          }

          if (customToggle) {
            customToggle.checked = false;
            customToggle.dataset.wasChecked = 'false';
          }
          customDiv.style.display = 'none';
          if (customInput) customInput.value = '';
        }
      });

      updatePagination();
    }

    // 动态高度调整
    function adjustContainerHeight() {
      const container = document.querySelector('.container');
      const windowHeight = window.innerHeight;
      const maxHeight = windowHeight - 40;
      container.style.maxHeight = `${maxHeight}px`;
      container.style.overflowY = 'auto';
    }

    window.addEventListener('resize', adjustContainerHeight);
    window.addEventListener('load', adjustContainerHeight);

    // 提交逻辑
    document.getElementById('submit-btn').addEventListener('click', () => {
      const selections = {};

      categories.forEach(category => {
        if (category.type === 'radio') {
          const selected = document.querySelector(`input[name="${category.name}"]:checked`);
          selections[category.name] = selected
            ? selected.value === '自定义'
              ? document.getElementById(`${category.name}-custom-input`)?.value.trim() || '未指定'
              : selected.value
            : '无';
        } else {
          const selected = document.querySelectorAll(`input[name="${category.name}"]:checked`);
          const values = Array.from(selected).map(cb => cb.value).filter(v => v !== '自定义');
          const customToggle = document.querySelector(`input[name="${category.name}-custom-toggle"]:checked`);
          if (customToggle) {
            const customValue = document.getElementById(`${category.name}-custom-input`)?.value.trim();
            if (customValue) values.push(customValue);
          }
          selections[category.name] = values.length ? values.join(', ') : '无';
        }
      });

      const message = `遴选条件:\n${Object.entries(selections)
        .map(([key, value]) => `${categories.find(c => c.name === key).label}: ${value}`)
        .join('\n')}`;

      if (typeof triggerSlash === 'function') {
        triggerSlash(`/setinput ${message}`);
      } else {
        console.log(message);
        alert(`已选择:\n${message}`);
      }
    });

    // 绑定随机按钮事件
    document.getElementById('random-btn').addEventListener('click', () => {
      randomSelect();
    });

    // 初始化
    renderPages();
    bindEvents();
    updatePagination();
  </script>
</body>
</html>
